# LAMMPS input script for elastic constants calculation

# Initialization
units metal
atom_style atomic
boundary p p p

# Read structure
read_data Al.data

# EAM potential for Al
pair_style eam/alloy
pair_coeff * * /potentials/Al_nist.eam.alloy Al

# Energy minimization
minimize 1.0e-10 1.0e-10 100000 100000

# Set up elastic calculation
change_box all triclinic

# Calculate elastic constants
fix 1 all box/relax aniso 0.0

# Define the elastic constants calculation
fix 2 all elastic/atom

# Run elastic constants calculation
variable up equal 1.0e-6
variable down equal -${up}

# C11
variable dir equal 1
include displace.mod

# C22
variable dir equal 2
include displace.mod

# C33
variable dir equal 3
include displace.mod

# C44
variable dir equal 4
include displace.mod

# C55
variable dir equal 5
include displace.mod

# C66
variable dir equal 6
include displace.mod

# Output elastic constants
variable C11 equal ${c11}
variable C12 equal ${c12}
variable C13 equal ${c13}
variable C14 equal ${c14}
variable C15 equal ${c15}
variable C16 equal ${c16}
variable C22 equal ${c22}
variable C23 equal ${c23}
variable C24 equal ${c24}
variable C25 equal ${c25}
variable C26 equal ${c26}
variable C33 equal ${c33}
variable C34 equal ${c34}
variable C35 equal ${c35}
variable C36 equal ${c36}
variable C44 equal ${c44}
variable C45 equal ${c45}
variable C46 equal ${c46}
variable C55 equal ${c55}
variable C56 equal ${c56}
variable C66 equal ${c66}

# Calculate bulk modulus (Voigt average)
variable B equal (${C11}+${C22}+${C33}+2*(${C12}+${C23}+${C13}))/9.0

print "Bulk modulus = ${B} GPa"

# Elastic constants calculation by finite deformations

# Positive deformation for C11
variable dir equal 1
variable up equal ${delta}
include /potentials/strain.mod
variable C11pos equal ${pxx}

# Negative deformation for C11
variable up equal -${delta}
include /potentials/strain.mod
variable C11neg equal ${pxx}

# Positive deformation for C22
variable dir equal 2
variable up equal ${delta}
include /potentials/strain.mod
variable C22pos equal ${pyy}

# Negative deformation for C22
variable up equal -${delta}
include /potentials/strain.mod
variable C22neg equal ${pyy}

# Positive deformation for C33
variable dir equal 3
variable up equal ${delta}
include /potentials/strain.mod
variable C33pos equal ${pzz}

# Negative deformation for C33
variable up equal -${delta}
include /potentials/strain.mod
variable C33neg equal ${pzz}

# C44
variable dir equal 4
variable up equal ${delta}
include /potentials/strain.mod
variable C44pos equal ${pyz}

# C44 negative
variable up equal -${delta}
include /potentials/strain.mod
variable C44neg equal ${pyz}

# C55
variable dir equal 5
variable up equal ${delta}
include /potentials/strain.mod
variable C55pos equal ${pxz}

# C55 negative
variable up equal -${delta}
include /potentials/strain.mod
variable C55neg equal ${pxz}

# C66
variable dir equal 6
variable up equal ${delta}
include /potentials/strain.mod
variable C66pos equal ${pxy}

# C66 negative
variable up equal -${delta}
include /potentials/strain.mod
variable C66neg equal ${pxy}

# Output elastic constants
variable C11 equal (${C11pos}-${C11neg})/(2.0*${delta})
variable C22 equal (${C22pos}-${C22neg})/(2.0*${delta})
variable C33 equal (${C33pos}-${C33neg})/(2.0*${delta})
variable C44 equal (${C44pos}-${C44neg})/(2.0*${delta})
variable C55 equal (${C55pos}-${C55neg})/(2.0*${delta})
variable C66 equal (${C66pos}-${C66neg})/(2.0*${delta})

# Calculate bulk modulus (Voigt average)
variable B equal (${C11}+${C22}+${C33})/9.0

print "C11 = ${C11}"
print "C22 = ${C22}"
print "C33 = ${C33}"
print "C44 = ${C44}"
print "C55 = ${C55}"
print "C66 = ${C66}"
print "Bulk modulus = ${B}"
